const postback = $json.latestPostback || $json.postback;
const productId = postback.replace('ADD_', '');

return [{ json: { productId } }];

const product = $input.first().json;
const senderId = $('Listen').first().json.senderId;
const priceFormat = p => (p ? `₱${p}` : '');

const isBite = product.ProductID && product.ProductID.startsWith('BK-');

if (isBite) {
  // For bites, create a postback similar to the drink format but with NONE for size and add-on
  return [{
    json: {
      sendSizeButtons: false,
      sizeSelected: false,
      message: `Selected: ${product.Name} (${priceFormat(product.BasePrice)}). Adding to cart...`,
      senderId,
      isBitesSelected: true,
      // Create postback in the same format as drinks but with NONE values
      postback: `${product.ProductID}|NONE|NONE`,
      type: "postback"
    }
  }];
}

const sizes = Array.isArray(product.Sizes) ? product.Sizes : [];

if (sizes.length === 0) {
  return [{
    json: {
      sendSizeButtons: false,
      sizeSelected: false,
      message: `Selected: ${product.Name} (${priceFormat(product.BasePrice)}). Added to cart!`,
      senderId
    }
  }];
}

const buttons = sizes.map(s => ({
  type: "postback",
  title: `${s.Size} - ${priceFormat(s.BasePrice)}`,
  payload: `${product.ProductID}|${s.Size}`
}));

return [{
  json: {
    sendSizeButtons: true,
    sizeSelected: false,
    recipient_id: senderId,
    message: `Choose a size for your ${product.Name}:`,
    buttons
  }
}];

const desiredProductIDs = [
  "CF-SPL",
  "CF-SCA",
  "FT-GAP",
  "MT-MAT",
  "MT-OKI",
  "MT-WIN"
];

const senderId = $('Listen').first().json.senderId;

const menuItems = $input.all().map(i => i.json);

const filteredItems = menuItems.filter(item =>
  desiredProductIDs.includes(item.ProductID) && item.isEnabled
);

const elements = filteredItems.map(item => ({
  title: item.Name,
  image_url: (item.imagelink && item.imagelink !== "placeholder")
    ? item.imagelink
    : `https://via.placeholder.com/300x200?text=${encodeURIComponent(item.Name)}`,
  subtitle: item.description || "No description available",
  buttons: [
    {
      type: "postback",
      title: "Add to Cart",
      payload: `ADD_${item.ProductID}`
    }
  ]
}));

elements.push({
  title: "Main Menu",
  image_url: "https://via.placeholder.com/300x200?text=Main+Menu",
  subtitle: "Return to main menu",
  buttons: [
    {
      type: "postback",
      title: "Go Back",
      payload: "REVIEW_MENU"
    }
  ]
});

const responsePayload = {
  messaging_type: "RESPONSE",
  recipient: { id: senderId },
  message: {
    attachment: {
      type: "template",
      payload: {
        template_type: "generic",
        elements: elements
      }
    }
  }
};

return [{ json: responsePayload }];

// Extract real sender ID from incoming data, adjust path if needed
const senderId = $('Listen').first().json.senderId;

if (!senderId) {
  throw new Error("Sender ID not found in input data");
}

// Get all menu items from input (e.g. from MongoDB node output)
const menuItems = $input.all().map(i => i.json);

// Filter to ProductIDs that start with "FT", and are enabled + available
const filteredItems = menuItems.filter(item =>
  item.ProductID && item.ProductID.startsWith("FT") && item.isEnabled
);

// Map filtered items into Messenger carousel elements, using description for subtitle
const elements = filteredItems.map(item => ({
  title: item.Name + " Fruit Tea",
  image_url: (item.imagelink && item.imagelink !== "placeholder")
    ? item.imagelink
    : `https://via.placeholder.com/300x200?text=${encodeURIComponent(item.Name)}`,
  subtitle: item.description || "No description available",
  buttons: [
    {
      type: "postback",
      title: "Add to Cart",
      payload: `ADD_${item.ProductID}`
    }
  ]
}));

// Add the "Main Menu" navigation card
elements.push({
  title: "Main Menu",
  image_url: "https://via.placeholder.com/300x200?text=Main+Menu",
  subtitle: "Return to main menu",
  buttons: [
    {
      type: "postback",
      title: "Go Back",
      payload: "REVIEW_MENU"
    }
  ]
});

const responsePayload = {
  messaging_type: "RESPONSE",
  recipient: { id: senderId },
  message: {
    attachment: {
      type: "template",
      payload: {
        template_type: "generic",
        elements: elements
      }
    }
  }
};

// Return the payload as one item, array format required by n8n
