        </div>
        <button type="submit" class="button" id="submitButton">Confirm Pickup Order</button>
        <div class="loading" id="loading">
          <div class="spinner"></div>
          <p>Confirming your pickup order...</p>
        </div>
        <div class="success-message message" id="successMessage">
          Your pickup order has been confirmed successfully!
        </div>
        <div class="error-message message" id="errorMessage">
          There was a problem confirming your order. Please try again.
        </div>
      </form>
    </div>
    <div class="footer">
      <p>© 2025 Blessings Cafe</p>
    </div>
  </div>
  <script>
    document.addEventListener('DOMContentLoaded', function () {
      let total = 0;
      let items = [];
      // Try to get data from previous node in n8n (function node output)
      if (typeof window.previousNodeOutput !== "undefined" && window.previousNodeOutput) {
        if (Array.isArray(window.previousNodeOutput)) {
          // Handle n8n output as array of objects [{items, total}]
          const output = window.previousNodeOutput[0];
          items = output.items || [];
          total = output.total || 0;
        } else if (typeof window.previousNodeOutput === "object") {
          // Handle n8n output as a single object {items, total}
          items = window.previousNodeOutput.items || [];
          total = window.previousNodeOutput.total || 0;
        }
      }
      // If not found, fallback: Try to get values from window.orderData (for testing/dev)
      if ((!items || !items.length) && window.orderData) {
        if (Array.isArray(window.orderData.items)) {
          items = window.orderData.items;
          total = window.orderData.total || items.reduce((sum, i) => sum + (Number(i.totalPrice) || 0), 0);
        }
      }
      const orderItemsContainer = document.getElementById('orderItems');
      if (items.length > 0) {
        orderItemsContainer.innerHTML = items.map(item => `
          <div class="order-item">
            <span class="item-name">${item.productName} ${item.size ? `(${item.size})` : ''} x${item.quantity}</span>
            <span class="item-price">₱${item.totalPrice}</span>
          </div>
        `).join('');
      }
      document.getElementById('orderTotal').textContent = total;
      document.getElementById('checkboxTotal').textContent = total;
      document.getElementById('orderTotalInput').value = total;
      let psid = '';
      if (window.previousNodeOutput && typeof window.previousNodeOutput.psid === "string" && window.previousNodeOutput.psid) {
        psid = window.previousNodeOutput.psid;
      } else {
        const urlParams = new URLSearchParams(window.location.search);
        psid = urlParams.get('psid') || '';
      }
      document.getElementById('psid').value = psid;
      const phoneInput = document.getElementById('phone');
      phoneInput.addEventListener('input', function() {
        let val = phoneInput.value;
        if (val.length === 1 && val === '9') {
          phoneInput.value = '0' + val;
        }
      });
      const form = document.getElementById('pickupForm');
      form.addEventListener('submit', submitForm);
    });
    function normalizePhoneNumber(phone) {
      let cleaned = phone.replace(/[\s\-\(\)\.]/g, '');
      if (cleaned.startsWith('+63')) {
        return '0' + cleaned.slice(3);
      } else if (cleaned.startsWith('63') && cleaned.length === 12) {
        return '0' + cleaned.slice(2);
      } else if (cleaned.startsWith('09') && cleaned.length === 11) {
        return cleaned;
      } else if (cleaned.startsWith('9') && cleaned.length === 10) {
        return '0' + cleaned;
      }
      return cleaned;
    }
    function isValidPhoneNumber(normalizedPhone) {
      return /^09\d{9}$/.test(normalizedPhone);
    }
    function validateForm() {
      let valid = true;
      const fullName = document.getElementById('fullName').value.trim();
      if (!fullName) {
        document.getElementById('fullNameError').style.display = 'block';
        valid = false;
      } else {
        document.getElementById('fullNameError').style.display = 'none';
      }
      const phoneValue = document.getElementById('phone').value.trim();
      const normalizedPhone = normalizePhoneNumber(phoneValue);
      if (!phoneValue || !isValidPhoneNumber(normalizedPhone)) {
        document.getElementById('phoneError').style.display = 'block';
        valid = false;
      } else {
        document.getElementById('phoneError').style.display = 'none';
      }
      const paymentCommit = document.getElementById('paymentCommit').checked;
      if (!paymentCommit) {
        document.getElementById('commitError').style.display = 'block';
        valid = false;
      } else {
        document.getElementById('commitError').style.display = 'none';
      }
      return valid;
    }
    async function submitForm(event) {
      event.preventDefault();
      document.getElementById('successMessage').style.display = 'none';
      document.getElementById('errorMessage').style.display = 'none';
      if (!validateForm()) {
        return;
      }
      document.getElementById('loading').style.display = 'block';
      document.getElementById('submitButton').disabled = true;
      const phoneValue = document.getElementById('phone').value.trim();
      const normalizedPhone = normalizePhoneNumber(phoneValue);
      const formData = {
        psid: document.getElementById('psid').value,
        fullName: document.getElementById('fullName').value.trim(),
        phone: normalizedPhone,
        pickupTime: document.getElementById('pickupTime').value,
        instructions: document.getElementById('instructions').value.trim(),
        orderTotal: document.getElementById('orderTotalInput').value,
        paymentCommitted: true,
        submittedAt: new Date().toISOString()
      };
      try {
        const response = await fetch('https://regularly-helped-terrapin.ngrok-free.app/webhook-test/confirm-pickup', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'ngrok-skip-browser-warning': 'true',
          },
          body: JSON.stringify(formData),
        });
        if (response.ok) {
          document.getElementById('successMessage').textContent =
            'Your pickup order has been confirmed! We will start preparing your order and notify you when it\'s ready.';
          document.getElementById('successMessage').style.display = 'block';
          document.getElementById('errorMessage').style.display = 'none';
          setTimeout(() => {
            if (window.MessengerExtensions) {
              MessengerExtensions.requestCloseBrowser(
                () => {},
                (err) => {}
              );
            }
          }, 3000);
        } else {
          document.getElementById('errorMessage').style.display = 'block';
        }
      } catch (error) {
        document.getElementById('errorMessage').style.display = 'block';
      } finally {
        document.getElementById('loading').style.display = 'none';
        document.getElementById('submitButton').disabled = false;
      }
    }
  </script>
</body>
</html>

