parameters.jsCode:
const allItems = $input.all();

let orderData;
if (allItems.length > 0) {
  orderData = allItems[0].json;
  if (Array.isArray(orderData)) {
    orderData = orderData[0];
  }
}

let cartItems = [];
if (orderData && Array.isArray(orderData.items)) {
  cartItems = orderData.items;
}

const parsedItems = cartItems.map(item => ({
  productId: item.productId,
  productName: item.productName,
  category: item.category,
  basePrice: item.basePrice,
  size: item.size,
  quantity: item.quantity,
  addOns: item.addOns || [],
  totalPrice: item.totalPrice,
  timestamp: item.timestamp
}));

const total = cartItems.reduce((sum, item) => sum + (Number(item.totalPrice) || 0), 0);

let psid = '';
if (cartItems.length > 0) {
  psid = cartItems[0].userId || '';
}

return {
  items: parsedItems,
  total: total,
  psid: psid,
  html: `<script>window.previousNodeOutput = ${JSON.stringify({items: parsedItems, total: total, psid: psid})};</script>`
};

const productId = $items("extract values")[0].json.ProductID || $items("extract values")[0].json.productId; // adjust the key name as needed
const inputSize = $items("extract values")[0].json.size;

if (productId && productId.startsWith("BK-")) {
  // If ProductID starts with BK-, bypass filtering and return original Sizes array unfiltered
  return items;
} 

// Otherwise, filter Sizes array by inputSize
items[0].json.Sizes = items[0].json.Sizes.filter(item => item.Size === inputSize);
return items;

const now = new Date();
const philippinesTime = new Date(now.getTime() + 8 * 60 * 60 * 1000);
const formattedDate = philippinesTime.toISOString();

function pad(num, size = 2) {
  return num.toString().padStart(size, '0');
}
const idDate =
  pad(philippinesTime.getMonth() + 1) +
  pad(philippinesTime.getDate()) +
  pad(philippinesTime.getHours()) +
  pad(philippinesTime.getMinutes()) +
  pad(philippinesTime.getSeconds());
const transactionId = `${idDate}-BLESSINGSCAFE`;

const rawInput = $input.item.json;

let psid = "unknown";
let items = [];
let subtotal = 0;
let itemCount = 0;
let createdAt = formattedDate;

// Extract from body for form/POST (webhook) flows
let formData;
try {
  if (rawInput.body && typeof rawInput.body === 'object') {
    formData = rawInput.body;
  } else if (rawInput.body && typeof rawInput.body === 'string') {
    formData = JSON.parse(rawInput.body);
  } else {
    formData = rawInput;
  }
  psid = formData.psid || rawInput.psid || rawInput.senderId || "unknown";
} catch (e) {
  formData = rawInput;
  psid = formData.psid || "unknown";
}

// Items and subtotal
items = formData.items || [];
// Try to get subtotal from orderTotal or sum items
if (typeof formData.orderTotal !== "undefined" && !isNaN(Number(formData.orderTotal))) {
  subtotal = Number(formData.orderTotal);
} else if (Array.isArray(items)) {
  subtotal = items.reduce((sum, i) => sum + (Number(i.totalPrice) || 0), 0);
} else {
  subtotal = 0;
}
itemCount = Array.isArray(items) ? items.length : 0;

const deliveryAddress = {
  email: null,
  phone: null,
  street: null,
  barangay: null,
  city: null,
  landmarks: null,
  notes: null,
  fullAddress: null,
  isDeliverable: false
};

return {
  json: {
    userId: psid,
    items: items,
    itemCount: itemCount,
    createdAt: createdAt,
    updatedAt: formattedDate,
    subtotal: subtotal,
    deliveryAddress: deliveryAddress,
    deliveryMethod: "PICKUP",
    transactionId: transactionId
  }
}

const input = $input.first().json;

function formatDatePH(dateStr) {
  const date = new Date(dateStr);
  const offset = 8 * 60; // Philippines is UTC+8
  const localDate = new Date(date.getTime() + offset * 60000);
  const y = localDate.getFullYear();
  const m = String(localDate.getMonth() + 1).padStart(2, '0');
  const d = String(localDate.getDate()).padStart(2, '0');
  const h = String(localDate.getHours()).padStart(2, '0');
  const min = String(localDate.getMinutes()).padStart(2, '0');
  const s = String(localDate.getSeconds()).padStart(2, '0');
  return `${y}-${m}-${d} ${h}:${min}:${s}`;
}

const orderCart = input.items.map(item => ({
  ProductID: item.productId,
  ProductName: item.productName,
  Quantity: item.quantity,
  Size: item.size,
  BasePrice: item.basePrice
}));

const order = {
  OrderID: input.transactionId || "",
  Date: formatDatePH(input.updatedAt || input.createdAt),
  Cart: orderCart,
  Customer: input.userId || "Unknown",
  ContactNumber: input.deliveryAddress?.phone || "",
  PaymentStatus: "Pending",
  PaymentMode: input.paymentMethod || "Cash on Hand",
  Total: input.subtotal,
  ItemTotal: input.itemCount || orderCart.reduce((sum, i) => sum + (i.Quantity || 1), 0),
  DeliveryStatus: input.deliveryMethod === "DELIVERY" ? "Delivery" : (input.deliveryMethod === "PICKUP" ? "Pick-Up" : "Take-Out"),
  Address: input.deliveryAddress?.fullAddress || "",
  Notes: input.deliveryAddress?.notes || "",
  FulfillmentStatus: "Preparing",
  Source: "Chatbot"
};

return [{ json: order }];
